  function deriveK(dBytes, eBytes, message, counter) {
    const h = sm3Bytes(dBytes.concat(eBytes, message, [counter & 0xff]))
    const k = hexToLimbs(bytesToHex(h))
    if (isZero(k) || cmp(k, N) >= 0) return null
    return k
  }

